# Artificer · Dark — eza colours
# Source this from ~/.zshrc. eza reads EZA_COLORS on every invocation, so no
# reload step is needed beyond starting a new shell.
#
# Generated from themes/_palette.json — edit there + re-run build.mjs.
# This is LS_COLORS grammar, not hex: 38;2;R;G;B is an SGR truecolor escape.
# Permission slots match yazi's [status] perm_read / perm_write / perm_exec so
# the two file listers agree.

export EZA_COLORS="di=38;2;159;182;196:ex=38;2;74;138;94:ln=38;2;125;166;164:or=38;2;160;69;64:pi=38;2;214;147;106:so=38;2;176;149;224:bd=38;2;214;147;106:cd=38;2;214;147;106:ur=38;2;219;187;111:uw=38;2;214;147;106:ux=38;2;74;138;94:ue=38;2;74;138;94:gr=38;2;219;187;111:gw=38;2;214;147;106:gx=38;2;74;138;94:tr=38;2;219;187;111:tw=38;2;214;147;106:tx=38;2;74;138;94:su=38;2;160;69;64:sf=38;2;160;69;64:xa=38;2;90;122;138:sn=38;2;232;230;225:sb=38;2;90;122;138:uu=38;2;219;187;111:un=38;2;90;122;138:gu=38;2;219;187;111:gn=38;2;90;122;138:da=38;2;90;122;138:ga=38;2;74;138;94:gm=38;2;214;147;106:gd=38;2;160;69;64:gv=38;2;176;149;224:gt=38;2;125;166;164:xx=38;2;74;79;92"